def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    rich_aggressive = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if bid >= 120 and opp.get('budget', 0) >= 120:
                    rich_aggressive += 1

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 5.0))

    high_pressure = max(prev_bids) if prev_bids else 0.0
    avg_pressure = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days >= 1:
        urgency += 0.45

    if supply >= 23 and urgency < 1.0:
        base = 1.0
    elif supply >= 20 and urgency < 0.8:
        base = 4.0
    elif supply >= 18:
        base = 8.0 + 8.0 * urgency
    else:
        base = 18.0 + 18.0 * urgency

    if high_pressure >= 150:
        if urgency < 0.9:
            bid = base
        else:
            bid = max(base, 0.78 * DAILY_SALARY + 8.0 * scarcity)
    elif high_pressure >= 100:
        if urgency < 0.7 and supply >= 19:
            bid = base
        else:
            bid = max(base, min(high_pressure * 0.72, 62.0 + 10.0 * urgency))
    elif high_pressure > 0:
        target = high_pressure + 2.5
        bid = max(base, min(target, 58.0 + 8.0 * urgency))
    else:
        bid = base + 6.0 * scarcity

    if rich_aggressive >= 2 and urgency < 1.0 and supply >= 19:
        bid = min(bid, 6.0)

    if desperate_count >= 2 and supply <= 18:
        bid = max(bid, 42.0 + 10.0 * urgency)

    if day >= 8:
        bid += 6.0 * urgency + 4.0 * scarcity

    reserve_floor = 0.0
    if hp > 4 and no_water_days == 0:
        reserve_floor = budget * 0.18
    max_spend = budget - reserve_floor
    if max_spend < 0:
        max_spend = budget

    bid = min(bid, max_spend)

    if urgency >= 1.5:
        bid = max(bid, min(budget, 68.0))
    elif urgency >= 1.0:
        bid = max(bid, min(budget, 52.0 + 10.0 * scarcity))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from immediate previous_trace only
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace') or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = 0.0
    if len(yesterday_bids) >= 2:
        sorted_b = sorted(yesterday_bids, reverse=True)
        second_prev_bid = float(sorted_b[1])

    # Supply pressure: higher supply reduces need to outbid
    # Normalize supply into [0,1]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_factor = 0.5
    else:
        supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_factor < 0.0:
            supply_factor = 0.0
        if supply_factor > 1.0:
            supply_factor = 1.0

    # Base aggressiveness: aim to beat typical top bids only when necessary
    # If yesterday highest bid was very high, opponents likely contest harder today.
    contest_mode = highest_prev_bid >= (DAILY_SALARY * 0.9)

    # If my HP is critical, bid harder regardless of supply.
    # Also if I've already had several no-water days, increase urgency.
    urgency = 0.0
    if hp <= 2.0:
        urgency += 1.0
    if no_water_days >= 2:
        urgency += 0.6
    if hp <= 4.0:
        urgency += 0.4

    # Target bid construction
    # - In low supply (supply_factor low), slightly higher bids.
    # - In high supply, bid lower.
    # - If contest_mode, try to slightly undercut the likely highest bidder rather than chase max.
    if contest_mode:
        # Try to be competitive but not maximal: just above second-highest (or a fraction of highest)
        target = max(DAILY_SALARY * (0.55 + 0.25 * (1.0 - supply_factor)),
                     (second_prev_bid + 1.0) if second_prev_bid > 0.0 else (highest_prev_bid * 0.75))
    else:
        target = max(DAILY_SALARY * (0.45 + 0.25 * (1.0 - supply_factor)),
                     (second_prev_bid + 0.5) if second_prev_bid > 0.0 else (DAILY_SALARY * 0.5))

    # Apply urgency boost
    if urgency >= 1.0:
        target = max(target, DAILY_SALARY * 0.9)
    elif urgency >= 0.6:
        target = max(target, DAILY_SALARY * 0.75)
    elif urgency >= 0.4:
        target = max(target, DAILY_SALARY * 0.65)

    # Budget safety: never exceed budget
    # Also avoid spending too much early if not urgent
    spend_cap = budget
    if urgency < 0.6 and day <= 5:
        spend_cap = min(spend_cap, DAILY_SALARY * 0.65)

    bid = min(spend_cap, target)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    bid_amount = DAILY_SALARY * 0.75

    if my_hp <= 2:
        bid_amount = DAILY_SALARY * 1.25
    elif my_hp <= 4:
        bid_amount = DAILY_SALARY * 1.05

    strong_opponents_yesterday_bids = []
    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev_trace = opp_data.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                # Identify strong opponents dynamically based on their salary and previous bid
                if opp_data['daily_salary'] >= DAILY_SALARY * 0.9 and prev_trace['bid'] >= opp_data['daily_salary'] * 0.8:
                    strong_opponents_yesterday_bids.append(prev_trace['bid'])
                # Also include opponents who bid very high regardless of their salary
                elif prev_trace['bid'] > DAILY_SALARY * 0.9:
                     strong_opponents_yesterday_bids.append(prev_trace['bid'])

    if strong_opponents_yesterday_bids:
        highest_strong_bid = max(strong_opponents_yesterday_bids)
        if highest_strong_bid > bid_amount * 0.9:
            bid_amount = highest_strong_bid + 5
            if my_hp > 5:
                bid_amount = min(bid_amount, DAILY_SALARY * 1.15)
            else:
                bid_amount = min(bid_amount, DAILY_SALARY * 1.35)

    if current_supply < num_alive_opponents:
        bid_amount = max(bid_amount, DAILY_SALARY * 1.2)
    elif current_supply < num_alive_opponents * 1.5:
        bid_amount = max(bid_amount, DAILY_SALARY * 1.05)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2 and my_hp >= 3:
        bid_amount = min(bid_amount, DAILY_SALARY * 0.8)
    elif remaining_days <= 2 and my_hp < 3:
        bid_amount = max(bid_amount, DAILY_SALARY * 1.3)

    final_bid = min(my_budget, bid_amount)

    if final_bid < 1.0 and my_budget > 0:
        final_bid = 1.0
    elif my_budget == 0:
        final_bid = 0.0

    return final_bid
